    def test_case_insensitive(self):
        """Case should be ignored."""
        self.assertTrue(is_anagram('ABC', 'abc'))
        self.assertTrue(is_anagram('AbC', 'aBc'))

    def test_mixed_case_and_spaces(self):
        """Mixed case and spaces should be handled correctly."""
        self.assertTrue(is_anagram('Hello World', 'hello world'))
        self.assertFalse(is_anagram('Hello World', 'hello worl'))

