import unittest


class TestDeliveryFee(unittest.TestCase):
    def test_zero_distance(self):
        """A delivery to the same location should cost exactly BASE_FEE."""
        self.assertAlmostEqual(delivery.delivery_fee((0, 0), (0, 0)), 2.00, places=5)

    def test_one_km_distance(self):
        """A 1 km delivery should cost $2.01 (BASE_FEE + PER_KM)."""
        self.assertAlmostEqual(delivery.delivery_fee((0, 0), (0, 1)), 2.01, places=5)

    def test_ten_km_distance(self):
        """A 10 km delivery should cost $2.01 (same as 1 km per the requirement)."""
        self.assertAlmostEqual(delivery.delivery_fee((0, 0), (0, 10)), 2.01, places=5)

    def test_far_distance(self):
        """A very far delivery should still cap at $2.01, not grow with distance."""
        self.assertAlmostEqual(delivery.delivery_fee((0, 0), (0, 1000)), 2.01, places=5)

    def test_negative_distance(self):
        """Negative distance (if possible) should not break; cap at $2.01."""
        self.assertAlmostEqual(delivery.delivery_fee((0, 0), (0, -1000)), 2.01, places=5)

    def test_rounding_precision(self):
        """Fee should be rounded to 2 decimal places."""
        fee = delivery.delivery_fee((0, 0), (0, 1))
        self.assertEqual(fee, round(fee, 2))

    def test_base_fee_constant(self):
        """BASE_FEE should remain 2.00 dollars."""
        self.assertEqual(delivery.BASE_FEE, 2.00)

    def test_per_km_constant(self):
        """PER_KM should remain 0.50 dollars per kilometre."""
        self.assertEqual(delivery.PER_KM, 0.50)

