    """Test that plugin names are case-insensitive (uppercase input)."""
    try:
        plugins.run('Resize')
    except KeyError:
        raise AssertionError("plugins.run('Resize') should not raise KeyError")

# Test 3: Non-existent plugin raises KeyError
def test_nonexistent_plugin():
    """Test that a non-existent plugin raises KeyError."""
    try:
        plugins.run('nonexistent')
    except KeyError:
        pass
    else:
        raise AssertionError("plugins.run('nonexistent') should raise KeyError")

# Test 4: Plugin with arguments passes them through
