def parse_version(text):
    """'1.2.3' -> (1, 2, 3)"""
    if text is None:
        return None

    # Strip whitespace and optional leading 'v'
    text = text.strip()
    if text.startswith('v'):
        text = text[1:]

    # Split by '.'
    parts = text.split('.')

    # Must have exactly 3 parts
    if len(parts) != 3:
        return None

    # Each part must be a valid integer string (no leading zeros except for '0')
    for p in parts:
        if not p.isdigit():
            return None
        # Check for leading zeros (e.g., '01' is invalid, but '0' is fine)
        if len(p) > 1 and p[0] == '0':
            return None

    return tuple(int(p) for p in parts)
```

