import os


def count_lines(path):
    """Number of lines in a text file."""
    if os.path.getsize(path) == 0:
        return 0
    with open(path, encoding="utf-8") as f:
        content = f.read()
        return content.count("\n") + (1 if content and not content.endswith("\n") else 0)
