from textfmt import title_word


def title_case(text):
    """Title-case a phrase for display."""
    words = text.split()
    if not words:
        return ""
    result = [title_word(words[0], first=True)]
    for word in words[1:]:
        result.append(title_word(word, first=False))
    return " ".join(result)
