class TestValidZips(unittest.TestCase):
    def test_valid_zip_codes(self):
        """Test that valid 5-digit ZIP codes are kept."""
        self.assertEqual(valid_zips(["12345", "67890"]), ["12345", "67890"])

    def test_valid_zip_ranges(self):
        """Test that valid ZIP code ranges (5-digit-5-digit) are kept."""
        self.assertEqual(valid_zips(["12345-67890"]), ["12345-67890"])

    def test_invalid_codes_filtered(self):
        """Test that invalid ZIP codes are filtered out."""
        self.assertEqual(valid_zips(["1234", "123456", "12345-6789"]), [])

    def test_stripped_spaces(self):
        """Test that spaces are stripped from valid ZIP codes."""
        self.assertEqual(valid_zips([" 12345 ", "12345-67890"]), ["12345", "12345-67890"])

    def test_order_preserved(self):
        """Test that the order of valid ZIP codes is preserved."""
        self.assertEqual(valid_zips(["67890", "12345"]), ["67890", "12345"])

    def test_empty_input(self):
        """Test that empty input returns empty list."""
        self.assertEqual(valid_zips([]), [])

    def test_mixed_valid_invalid(self):
        """Test that only valid codes are kept from a mixed list."""
        self.assertEqual(valid_zips(["12345", "1234", "67890"]), ["12345", "67890"])

    def test_only_invalid(self):
        """Test that a list of only invalid codes returns empty list."""
        self.assertEqual(valid_zips(["1234", "123456"]), [])

