from solution import median_price


class TestMedianPrice(unittest.TestCase):
    """Tests for median_price in solution.py."""

    def test_single_item(self):
        """Median of a single item is that item's price."""
        self.assertEqual(median_price([{"price": 10}]), 10)

    def test_two_items_even_count(self):
        """Median of two items is the mean of the two prices."""
        self.assertEqual(median_price([{"price": 1}, {"price": 2}]), 1.0)

    def test_three_items_odd_count(self):
        """Median of three items is the middle price."""
        self.assertEqual(median_price([{"price": 1}, {"price": 2}, {"price": 3}]), 2)

    def test_four_items_even_count(self):
        """Median of four items is the mean of the two middle prices."""
        self.assertEqual(median_price([{"price": 1}, {"price": 2}, {"price": 3}, {"price": 4}]), 2.0)

    def test_even_count_with_float_prices(self):
        """Median of even count with float prices returns float mean."""
        self.assertEqual(median_price([{"price": 1.0}, {"price": 2.0}]), 1.0)

    def test_even_count_with_mixed_int_float(self):
        """Median of even count with mixed int/float prices returns float mean."""
        self.assertEqual(median_price([{"price": 1}, {"price": 2.0}]), 1.0)

    def test_even_count_with_unsorted(self):
        """Median of even count with unsorted prices returns correct mean."""
        self.assertEqual(median_price([{"price": 4}, {"price": 1}]), 1.0)

    def test_odd_count_with_unsorted(self):
        """Median of odd count with unsorted prices returns correct middle value."""
        self.assertEqual(median_price([{"price": 3}, {"price": 1}, {"price": 2}]), 2)

